SELECT T1.cName FROM College AS T1 WHERE T1.state = 'LA' AND T1.enr > 15000
UNION
SELECT T2.cName FROM College AS T2 WHERE T2.state = 'AZ' AND T2.enr >= 13000;

SELECT e.EMPLOYEE_ID, e.JOB_ID
FROM employees e
WHERE e.SALARY > (SELECT MAX(salary) FROM employees j WHERE j.JOB_ID = 'MK_MAN');

SELECT document_name, document_date 
FROM Documents 
WHERE Project_ID IN (SELECT Project_ID FROM Projects WHERE Project_Details != 'Graph Database project') ;

SELECT MIN(salary) 
FROM instructor 
WHERE dept_name IN (SELECT dept_name FROM instructor GROUP BY dept_name HAVING AVG(salary) <= (SELECT AVG(salary) FROM instructor));

SELECT Customers.email_address, Customers.phone_number 
FROM Customers
WHERE Customers.customer_id NOT IN (SELECT customer_id FROM Complaints);

SELECT AVG(LifeExpectancy) 
FROM country 
WHERE Code NOT IN (SELECT CountryCode FROM countrylanguage WHERE Language = 'English' AND IsOfficial = 'T');

SELECT professional_id, role_code, email_address
FROM Professionals
WHERE professional_id NOT IN (SELECT professional_id FROM Treatments);

SELECT Name 
FROM artwork
WHERE Artwork_ID NOT IN (SELECT Artwork_ID FROM nomination);

SELECT characteristic_name, other_characteristic_details, characteristic_data_type
FROM Characteristics
WHERE characteristic_id NOT IN (SELECT DISTINCT characteristic_id FROM Product_Characteristics);

SELECT c.characteristic_name, c.other_characteristic_details, c.characteristic_data_type 
FROM Characteristics AS c
WHERE c.characteristic_id NOT IN (SELECT DISTINCT characteristic_id FROM Product_Characteristics);
